def merge_intervals(xs):
    if not xs:
        return []

    xs.sort(key=lambda x: x[0])
    merged = [xs[0]]

    for start, end in xs[1:]:
        if merged[-1][1] >= start:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])

    return merged
```

