def count_islands(g):
    def dfs(i, j):
        if i < 0 or i >= len(g) or j < 0 or j >= len(g[0]) or g[i][j] == '0':
            return
        g[i][j] = '0'  # 标记为已访问
        dfs(i + 1, j)  # 下
        dfs(i - 1, j)  # 上
        dfs(i, j + 1)  # 右
        dfs(i, j - 1)  # 左

    count = 0
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j] == '1':
                dfs(i, j)
                count += 1
    return count
```

